<?php require_once __DIR__.'/../includes/staff/feature-tools.php';$pdo=staff_db();$rows=[];try{$rows=$pdo->query('SELECT * FROM project_gallery_entries WHERE is_published=1 ORDER BY is_featured DESC,sort_order,completion_date DESC')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Our Projects · IdeaRE</title><link rel="stylesheet" href="<?=h(ideare_root_url('assets/css/staff.css'))?>"><link rel="stylesheet" href="<?=h(ideare_root_url('assets/css/crm-projects.css'))?>"></head><body><main class="public-shell"><a href="<?=h(ideare_root_url('index.php'))?>">← IdeaRE</a><h1>Our Projects</h1><p>Selected cabinetry and interior projects completed by IdeaRE.</p><div class="public-grid"><?php foreach($rows as $r):?><article class="public-card"><?php if($r['cover_image']):?><img src="<?=h(ideare_root_url($r['cover_image']))?>" alt=""><?php endif?><div class="body"><small><?=h($r['category']?:'Project')?></small><h2><?=h($r['title'])?></h2><p><?=h($r['short_description']?:'')?></p><small><?=h($r['location_label']?:'')?> <?=h($r['completion_date']?:'')?></small></div></article><?php endforeach?></div></main></body></html>